/**
 * A faithful TypeScript port of the scoring and policy in
 * backend/app/adaptive/engine.py (ENGINE_VERSION 1.2.0) in the main Lumora
 * repository (github.com/Divyanshi12coder/lumora-adaptive-learning).
 *
 * It exists so the case study can run the engine interactively with no
 * backend. The product itself always calls the Python engine. Parity with
 * Python is checked by src/test/engine.test.ts against golden outputs that
 * were generated by running the real engine.
 */

export const ENGINE_VERSION = "1.2.0";

export const FAMILY_WEIGHTS = {
  performance: 0.3,
  mastery: 0.25,
  ml_struggle: 0.2,
  behaviour: 0.15,
  momentum: 0.1,
} as const;

export type Family = keyof typeof FAMILY_WEIGHTS;

export const COLD_START_PRIOR = 0.58;
export const FULL_CONFIDENCE_ATTEMPTS = 12;

export interface LearnerSignals {
  recent_accuracy: number | null;
  historical_accuracy: number | null;
  mastery: number;
  attempts: number;
  avg_response_ratio: number;
  hint_rate: number;
  skip_rate: number;
  mistake_streak: number;
  repeated_mistakes: number;
  answer_change_rate: number;
  low_confidence_rate: number;
  explanation_requests: number;
  session_minutes: number;
  days_since_practice: number | null;
  trend_slope: number;
  struggle_probability: number | null;
  engagement_probability: number | null;
}

export interface LearnerPreferences {
  explanation_length: "short" | "medium" | "detailed";
  prefers_visuals: boolean;
  prefers_examples: boolean;
  pace: "relaxed" | "steady" | "quick";
  length_bias: number;
  difficulty_bias: number;
}

export type Band = "high_support" | "guided" | "balanced" | "stretch";

export interface Factor {
  family: Family;
  need: number;
  weight: number;
}

export interface TeachingStrategy {
  band: Band;
  difficulty: "easy" | "medium" | "hard";
  explanation_style: "step_by_step" | "worked_example" | "guided_discovery" | "concise";
  content_density: "low" | "medium" | "high";
  hint_level: "none" | "light" | "guided" | "full";
  example_count: number;
  review_required: boolean;
  pacing: "slow" | "steady" | "brisk";
  visual_support: "low" | "medium" | "high";
  option_count: number;
  question_count: number;
  suggest_break: boolean;
  read_aloud_suggested: boolean;
  tone: "gentle" | "warm" | "celebratory";
  support_score: number;
  data_confidence: number;
  factors: Factor[];
}

export const DEFAULT_SIGNALS: LearnerSignals = {
  recent_accuracy: null,
  historical_accuracy: null,
  mastery: 0.2,
  attempts: 0,
  avg_response_ratio: 1,
  hint_rate: 0,
  skip_rate: 0,
  mistake_streak: 0,
  repeated_mistakes: 0,
  answer_change_rate: 0,
  low_confidence_rate: 0,
  explanation_requests: 0,
  session_minutes: 0,
  days_since_practice: null,
  trend_slope: 0,
  struggle_probability: null,
  engagement_probability: null,
};

export const DEFAULT_PREFS: LearnerPreferences = {
  explanation_length: "medium",
  prefers_visuals: true,
  prefers_examples: true,
  pace: "steady",
  length_bias: 0,
  difficulty_bias: 0,
};

const clip = (x: number, lo = 0, hi = 1) => Math.max(lo, Math.min(hi, x));
// toFixed rounds the exact binary value, like Python's round(x, 3); Math.round(x * 1000) does not.
const round3 = (x: number) => Number(x.toFixed(3));
/** Python's round(): halves go to the nearest even integer. */
const roundHalfEven = (x: number) => {
  const r = Math.round(x);
  return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
};

function score(s: LearnerSignals, p: LearnerPreferences) {
  const needs: [Family, number][] = [];

  if (s.recent_accuracy !== null || s.historical_accuracy !== null) {
    const recent = (s.recent_accuracy ?? s.historical_accuracy) as number;
    const hist = s.historical_accuracy ?? recent;
    needs.push(["performance", 1 - (0.65 * recent + 0.35 * hist)]);
  }
  needs.push(["mastery", 1 - clip(s.mastery)]);
  if (s.struggle_probability !== null) needs.push(["ml_struggle", clip(s.struggle_probability)]);

  const slow = clip((s.avg_response_ratio - 1) / 1.5);
  const behaviour =
    0.25 * clip(s.hint_rate) +
    0.2 * clip(s.mistake_streak / 3) +
    0.15 * clip(s.skip_rate * 2) +
    0.15 * slow +
    0.1 * clip(s.low_confidence_rate) +
    0.08 * clip(s.answer_change_rate) +
    0.07 * clip(s.explanation_requests / 3);
  needs.push(["behaviour", clip(behaviour)]);
  needs.push(["momentum", clip(0.5 - s.trend_slope * 10)]);

  const totalW = needs.reduce((acc, [k]) => acc + FAMILY_WEIGHTS[k], 0);
  const factors: Factor[] = needs.map(([family, need]) => ({
    family,
    need: round3(need),
    weight: round3(FAMILY_WEIGHTS[family] / totalW),
  }));
  const raw = factors.reduce((acc, f) => acc + f.need * f.weight, 0);
  const confidence = clip(s.attempts / FULL_CONFIDENCE_ATTEMPTS);
  let support = confidence * raw + (1 - confidence) * COLD_START_PRIOR;
  support += 0.12 * clip(p.difficulty_bias, -1, 1);
  return { support: clip(support), confidence, factors };
}

export function decideStrategy(signals: LearnerSignals, prefs: LearnerPreferences = DEFAULT_PREFS): TeachingStrategy {
  const { support: s, confidence, factors } = score(signals, prefs);

  let band: Band;
  let difficulty: TeachingStrategy["difficulty"];
  let style: TeachingStrategy["explanation_style"];
  if (s >= 0.68) [band, difficulty, style] = ["high_support", "easy", "step_by_step"];
  else if (s >= 0.52) [band, difficulty, style] = ["guided", signals.mastery < 0.35 ? "easy" : "medium", "worked_example"];
  else if (s >= 0.36) [band, difficulty, style] = ["balanced", "medium", "guided_discovery"];
  else [band, difficulty, style] = ["stretch", "hard", "concise"];

  const lowEngagement = signals.engagement_probability !== null && signals.engagement_probability < 0.4;
  let densityScore = 1 - s;
  densityScore += { short: -0.25, medium: 0, detailed: 0.2 }[prefs.explanation_length];
  densityScore -= 0.2 * clip(prefs.length_bias, -1, 1);
  if (lowEngagement) densityScore -= 0.2;
  let density: TeachingStrategy["content_density"] = densityScore < 0.42 ? "low" : densityScore < 0.7 ? "medium" : "high";
  if (density === "high" && prefs.explanation_length === "short") density = "medium";

  const hint: TeachingStrategy["hint_level"] = s >= 0.72 ? "full" : s >= 0.52 ? "guided" : s >= 0.33 ? "light" : "none";

  let examples = s >= 0.68 ? 3 : s >= 0.45 ? 2 : 1;
  if (prefs.prefers_examples) examples = Math.min(4, examples + 1);
  if (density === "low") examples = Math.min(examples, 2);

  const review =
    (signals.mastery < 0.4 && signals.attempts >= 4) ||
    signals.repeated_mistakes >= 2 ||
    (signals.days_since_practice !== null && signals.days_since_practice > 7 && signals.mastery < 0.85);

  let pacing: TeachingStrategy["pacing"];
  if (s >= 0.6 || prefs.pace === "relaxed") pacing = "slow";
  else if ((s < 0.36 && prefs.pace === "quick") || s < 0.3) pacing = "brisk";
  else pacing = "steady";

  const visual: TeachingStrategy["visual_support"] = prefs.prefers_visuals || s >= 0.7 ? "high" : s >= 0.4 ? "medium" : "low";
  const optionCount = s >= 0.68 ? 3 : 4;
  const questionCount = s >= 0.68 || lowEngagement ? 4 : band === "stretch" ? 6 : 5;

  let tone: TeachingStrategy["tone"];
  if (signals.mistake_streak >= 2 || s >= 0.68) tone = "gentle";
  else if (signals.trend_slope > 0.02 || (signals.recent_accuracy ?? 0) >= 0.85) tone = "celebratory";
  else tone = "warm";

  return {
    band,
    difficulty,
    explanation_style: style,
    content_density: density,
    hint_level: hint,
    example_count: examples,
    review_required: review,
    pacing,
    visual_support: visual,
    option_count: optionCount,
    question_count: questionCount,
    suggest_break: lowEngagement || signals.session_minutes >= 25,
    read_aloud_suggested: signals.avg_response_ratio > 1.8 && s >= 0.6,
    tone,
    support_score: round3(s),
    data_confidence: round3(confidence),
    factors,
  };
}

/** Port of `signals_for_level`: maps a 0-100 "how is the learner doing" level to plausible signals. */
export function signalsForLevel(level: number): LearnerSignals {
  const t = clip(level / 100);
  return {
    ...DEFAULT_SIGNALS,
    recent_accuracy: 0.2 + 0.78 * t,
    historical_accuracy: 0.3 + 0.6 * t,
    mastery: 0.08 + 0.88 * t,
    attempts: FULL_CONFIDENCE_ATTEMPTS,
    avg_response_ratio: 2.2 - 1.5 * t,
    hint_rate: clip(1.2 - 1.3 * t),
    skip_rate: clip(0.3 - 0.35 * t),
    mistake_streak: roundHalfEven(3 * (1 - t) ** 2),
    repeated_mistakes: t < 0.25 ? 2 : 0,
    low_confidence_rate: clip(0.7 - 0.8 * t),
    trend_slope: -0.02 + 0.05 * t,
    struggle_probability: clip(0.85 - 0.8 * t),
    engagement_probability: 0.55 + 0.4 * t,
    session_minutes: 10,
    days_since_practice: 1,
  };
}
